-- ===== migrations/0005_cambridge19_academic.sql =====

-- IELTS Pulse — Cambridge IELTS 19 Academic dataset
-- Stores full tests (all four skills bundled per test), listening/reading
-- questions with answer keys, writing task prompts, and speaking prompts.
-- Idempotent + RLS-enabled. Distinct from the 0002 "cambridge_engine" schema,
-- which models one row per section; this dataset bundles all skills per test.
--
-- NOTE ON ANSWER KEYS: per the integration request, the read policies below
-- grant anon + authenticated SELECT on every table, including the
-- `correct_answers` column. That means the answer key is reachable by any
-- client using the anon key. If/when these tests are used for graded practice,
-- move `ielts_questions` behind the service role (as 0002 does) and score
-- server-side instead — see lib/services/ielts.ts.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table if not exists public.ielts_tests (
  id          uuid primary key default gen_random_uuid(),
  book        text not null,
  test_number int  not null,
  created_at  timestamptz not null default now(),
  unique (book, test_number)
);

-- Listening + reading questions. Reading in this dataset is an answer key only
-- (no passages), so `prompt`/`label`/`part_number` are null for reading rows.
create table if not exists public.ielts_questions (
  id              uuid primary key default gen_random_uuid(),
  test_id         uuid not null references public.ielts_tests (id) on delete cascade,
  section         text not null check (section in ('listening', 'reading')),
  part_number     int,
  question_ref    text not null,
  sort_order      int  not null default 0,
  type            text check (type in (
                    'multiple_choice', 'multiple_choice_multiple', 'matching', 'matching_map'
                  )),
  prompt          text,
  label           text,
  correct_answers text[] not null,
  created_at      timestamptz not null default now(),
  unique (test_id, section, question_ref)
);

create table if not exists public.ielts_writing_tasks (
  id          uuid primary key default gen_random_uuid(),
  test_id     uuid not null references public.ielts_tests (id) on delete cascade,
  task_number int  not null,
  prompt      text not null,
  created_at  timestamptz not null default now(),
  unique (test_id, task_number)
);

create table if not exists public.ielts_speaking_prompts (
  id            uuid primary key default gen_random_uuid(),
  test_id       uuid not null references public.ielts_tests (id) on delete cascade,
  part_number   int  not null,
  category      text,          -- part 3 theme name; null for parts 1 & 2
  topic         text,          -- topic / cue card for parts 1 & 2
  prompt_points text[],        -- cue-card bullets (part 2)
  questions     text[],        -- discussion questions (parts 1 & 3)
  sort_order    int  not null default 0,
  created_at    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------------

create index if not exists ielts_questions_test_idx    on public.ielts_questions (test_id, section, sort_order);
create index if not exists ielts_writing_test_idx      on public.ielts_writing_tasks (test_id);
create index if not exists ielts_speaking_test_idx     on public.ielts_speaking_prompts (test_id, part_number, sort_order);

-- ---------------------------------------------------------------------------
-- Row Level Security — public/authenticated read access
-- ---------------------------------------------------------------------------

alter table public.ielts_tests            enable row level security;
alter table public.ielts_questions        enable row level security;
alter table public.ielts_writing_tasks    enable row level security;
alter table public.ielts_speaking_prompts enable row level security;

drop policy if exists "ielts_tests_read" on public.ielts_tests;
create policy "ielts_tests_read" on public.ielts_tests
  for select to anon, authenticated using (true);

drop policy if exists "ielts_questions_read" on public.ielts_questions;
create policy "ielts_questions_read" on public.ielts_questions
  for select to anon, authenticated using (true);

drop policy if exists "ielts_writing_read" on public.ielts_writing_tasks;
create policy "ielts_writing_read" on public.ielts_writing_tasks
  for select to anon, authenticated using (true);

drop policy if exists "ielts_speaking_read" on public.ielts_speaking_prompts;
create policy "ielts_speaking_read" on public.ielts_speaking_prompts
  for select to anon, authenticated using (true);

-- Writes are intentionally not granted to anon/authenticated: content is
-- loaded by the seed script through the service-role key, which bypasses RLS.

-- ===== migrations/0006_student_email.sql =====

-- Contact address for a student, used to invite them to the portal.
-- Nullable: the existing demo cohort has no addresses on file.
alter table public.students
  add column if not exists email text;

-- One address per student within a center; nulls are unaffected.
create unique index if not exists students_center_email_key
  on public.students (center_id, lower(email))
  where email is not null;

-- ===== migrations/0007_lessons.sql =====

-- EduFlow — course syllabus.
--
-- `lessons` holds the fixed programme for a centre; a group's position in it is
-- a single pointer on `groups`, so a group can never have two current lessons.

alter table public.groups
  add column if not exists current_lesson int not null default 1;

-- `add constraint if not exists` doesn't exist in Postgres, so guard on catalog.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'groups_current_lesson_positive'
  ) then
    alter table public.groups
      add constraint groups_current_lesson_positive check (current_lesson >= 1);
  end if;
end $$;

create table if not exists public.lessons (
  id             uuid primary key default gen_random_uuid(),
  center_id      uuid not null references public.language_centers (id) on delete cascade,
  number         int not null check (number >= 1),
  title          text not null,
  summary        text,
  skill          text not null default 'general'
                   check (skill in ('listening', 'reading', 'writing', 'speaking', 'general')),
  material_title text,
  material_url   text,
  created_at     timestamptz not null default now(),
  unique (center_id, number)
);

create index if not exists lessons_center_number_idx
  on public.lessons (center_id, number);

alter table public.lessons enable row level security;

-- Syllabus is readable by anyone in the centre and writable by its teachers.
drop policy if exists "lessons_rw_center" on public.lessons;
create policy "lessons_rw_center" on public.lessons
  for all
  using (center_id in (select public.current_user_center_ids()))
  with check (center_id in (select public.current_user_center_ids()));

-- ===== migrations/0008_admin_roles.sql =====

-- EduFlow — administrator/owner roles and group ownership.
--
-- The director dashboard needs two things the schema didn't have: a role above
-- "teacher", and a way to say which teacher runs which group.

-- Widen the role check. Drop-then-add because Postgres has no
-- `alter constraint ... check`.
alter table public.profiles drop constraint if exists profiles_role_check;
alter table public.profiles
  add constraint profiles_role_check
  check (role in ('owner', 'admin', 'teacher', 'student', 'parent'));

-- `teachers.role` gains the same top tier so the roster can show who is staff
-- leadership rather than a class teacher.
alter table public.teachers drop constraint if exists teachers_role_check;
alter table public.teachers
  add constraint teachers_role_check
  check (role in ('owner', 'admin', 'director', 'teacher'));

alter table public.groups
  add column if not exists teacher_id uuid references public.teachers (id) on delete set null;

create index if not exists groups_teacher_idx on public.groups (teacher_id);

-- Homework rows are seeded with fixed ids so re-seeding replaces rather than
-- duplicates them; this index keeps the director's pending-review query cheap.
create index if not exists hw_submissions_status_idx
  on public.homework_submissions (status, submitted_at);

-- ===== migrations/0009_exam_papers.sql =====

-- EduFlow — imported exam papers.
--
-- The paper is stored as one JSONB document rather than normalised into
-- passages/groups/questions tables: the engine already consumes a single
-- nested `ExamSectionFull`, nothing queries inside it, and keeping it whole
-- means an import round-trips byte-for-byte.
--
-- Answer keys live inside `payload`. Reads go through the service-role client
-- on the server, and the API strips keys before anything reaches a browser.

create table if not exists public.exam_papers (
  id            uuid primary key default gen_random_uuid(),
  center_id     uuid not null references public.language_centers (id) on delete cascade,
  -- Stable identifier used in URLs and by the engine (`ExamSection.id`).
  slug          text not null,
  title         text not null,
  skill         text not null check (skill in ('reading', 'listening')),
  duration_minutes int not null default 60 check (duration_minutes between 1 and 240),
  attribution   text,
  -- Denormalised counters so the catalogue lists papers without parsing JSON.
  passage_count int not null default 0,
  question_count int not null default 0,
  payload       jsonb not null,
  published     boolean not null default true,
  imported_by   text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (center_id, slug)
);

create index if not exists exam_papers_center_skill_idx
  on public.exam_papers (center_id, skill, published);

alter table public.exam_papers enable row level security;

drop policy if exists "exam_papers_rw_center" on public.exam_papers;
create policy "exam_papers_rw_center" on public.exam_papers
  for all
  using (center_id in (select public.current_user_center_ids()))
  with check (center_id in (select public.current_user_center_ids()));

-- ===== migrations/0010_vocabulary.sql =====

-- EduFlow — personal vocabulary.
--
-- Every row belongs to one student, including words a teacher assigns: the
-- learning status is the learner's, so two students working the same topic
-- keep independent progress on the same word.

create table if not exists public.vocabulary_entries (
  id          uuid primary key default gen_random_uuid(),
  center_id   uuid not null references public.language_centers (id) on delete cascade,
  student_id  uuid not null references public.students (id) on delete cascade,
  term        text not null,
  phonetic    text,
  translation text not null,
  -- The sentence the word was taken from, or a model sentence.
  example     text,
  source      text not null default 'student'
                check (source in ('student', 'teacher')),
  topic       text,
  status      text not null default 'new'
                check (status in ('new', 'learning', 'mastered')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  -- One entry per word per student; re-saving updates instead of duplicating.
  unique (student_id, term)
);

create index if not exists vocabulary_student_status_idx
  on public.vocabulary_entries (student_id, status);

alter table public.vocabulary_entries enable row level security;

drop policy if exists "vocabulary_rw_center" on public.vocabulary_entries;
create policy "vocabulary_rw_center" on public.vocabulary_entries
  for all
  using (center_id in (select public.current_user_center_ids()))
  with check (center_id in (select public.current_user_center_ids()));

-- ===== migrations/0011_auth_roles_guardianships.sql =====

-- EduFlow — Stage 1: roles, parent↔child links, and RLS for end-user auth.
--
-- Idempotent. This is the migration that lets the app read through the user's
-- own session (RLS enforced) instead of the service-role key. Until now every
-- policy was scoped through public.teachers, so a student or parent user would
-- see nothing; the helpers and policies below give those roles a real, minimal
-- window onto their own data.

-- ---------------------------------------------------------------------------
-- 1. Role constraint — assert the full five-role set.
--    0008 already widened this, but 0003 created the table with only three
--    roles. Re-asserting here removes any dependence on application order.
-- ---------------------------------------------------------------------------
alter table public.profiles drop constraint if exists profiles_role_check;
alter table public.profiles
  add constraint profiles_role_check
  check (role in ('owner', 'admin', 'teacher', 'student', 'parent'));

-- ---------------------------------------------------------------------------
-- 2. Parent ↔ child as a real many-to-many entity.
--    profiles.student_id stays usable for a STUDENT (their own row) but must no
--    longer be treated as the parent link — a parent may have several children.
-- ---------------------------------------------------------------------------
create table if not exists public.guardianships (
  id             uuid primary key default gen_random_uuid(),
  parent_user_id uuid not null references auth.users (id) on delete cascade,
  student_id     uuid not null references public.students (id) on delete cascade,
  created_at     timestamptz not null default now(),
  unique (parent_user_id, student_id)
);

create index if not exists guardianships_parent_idx
  on public.guardianships (parent_user_id);
create index if not exists guardianships_student_idx
  on public.guardianships (student_id);

-- ---------------------------------------------------------------------------
-- 3. Session helpers. SECURITY DEFINER so the lookup is not itself blocked by
--    RLS on profiles. STABLE: same result within a statement.
-- ---------------------------------------------------------------------------

-- The caller's role, or null when signed out.
create or replace function public.current_user_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role from public.profiles where id = auth.uid();
$$;

-- The student row a STUDENT account is pinned to (null for every other role).
create or replace function public.current_user_student_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select student_id
  from public.profiles
  where id = auth.uid() and role = 'student';
$$;

-- Student ids the caller is a guardian of. Empty for non-parents.
create or replace function public.current_user_ward_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select student_id from public.guardianships where parent_user_id = auth.uid();
$$;

-- ---------------------------------------------------------------------------
-- 4. guardianships RLS: a parent sees only their own links; staff of the
--    child's centre may read them (needed to manage families in Stage 2).
-- ---------------------------------------------------------------------------
alter table public.guardianships enable row level security;

drop policy if exists "guardianships_parent_select" on public.guardianships;
create policy "guardianships_parent_select" on public.guardianships
  for select using (parent_user_id = auth.uid());

drop policy if exists "guardianships_staff_select" on public.guardianships;
create policy "guardianships_staff_select" on public.guardianships
  for select using (
    student_id in (
      select id from public.students
      where center_id in (select public.current_user_center_ids())
    )
  );

-- ---------------------------------------------------------------------------
-- 5. Extra read windows on student data for the student and parent roles.
--    The existing "*_rw_center" policies (staff, via teachers) are kept as-is;
--    RLS ORs policies together, so these only ADD visibility, never widen the
--    staff scope. Students and parents get SELECT only — they never write a
--    student, mock test or recommendation row.
-- ---------------------------------------------------------------------------

-- students -----------------------------------------------------------------
drop policy if exists "students_self_select" on public.students;
create policy "students_self_select" on public.students
  for select using (id = public.current_user_student_id());

drop policy if exists "students_parent_select" on public.students;
create policy "students_parent_select" on public.students
  for select using (id in (select public.current_user_ward_ids()));

-- mock_tests ---------------------------------------------------------------
drop policy if exists "mock_tests_self_select" on public.mock_tests;
create policy "mock_tests_self_select" on public.mock_tests
  for select using (
    student_id = public.current_user_student_id()
    or student_id in (select public.current_user_ward_ids())
  );

-- recommendations ----------------------------------------------------------
drop policy if exists "recommendations_self_select" on public.recommendations;
create policy "recommendations_self_select" on public.recommendations
  for select using (
    student_id = public.current_user_student_id()
    or student_id in (select public.current_user_ward_ids())
  );

-- parent_reports -----------------------------------------------------------
drop policy if exists "parent_reports_self_select" on public.parent_reports;
create policy "parent_reports_self_select" on public.parent_reports
  for select using (
    student_id = public.current_user_student_id()
    or student_id in (select public.current_user_ward_ids())
  );

-- ===== migrations/0012_academic_structure.sql =====

-- EduFlow — Stage 2: academic structure.
--
-- Turns the string-based coupling (students.student_group = 'IELTS 62') into
-- real relations, WITHOUT dropping the strings: homework.group_name,
-- attendance.group_name and most of the UI still read them, and rewriting those
-- is Stage 3. The text column stays as the compatibility surface and is kept in
-- sync by a trigger, so both paths agree.
--
-- Also fills a gap found in Stage 1: `groups` had RLS enabled but not a single
-- policy, so it was invisible to every non-service-role reader.

-- ---------------------------------------------------------------------------
-- 1. Groups belong to a centre (they were global until now).
-- ---------------------------------------------------------------------------
alter table public.groups
  add column if not exists center_id uuid references public.language_centers (id) on delete cascade;

-- Single-tenant today: attach any orphan group to the one existing centre.
update public.groups g
   set center_id = (select id from public.language_centers order by created_at limit 1)
 where g.center_id is null;

create index if not exists groups_center_idx on public.groups (center_id);

-- ---------------------------------------------------------------------------
-- 2. Courses — the syllabus a group follows. `lessons` already holds the
--    24-lesson programme per centre; a course names it and lets a centre run
--    more than one programme later.
-- ---------------------------------------------------------------------------
create table if not exists public.courses (
  id           uuid primary key default gen_random_uuid(),
  center_id    uuid not null references public.language_centers (id) on delete cascade,
  name         text not null,
  description  text,
  total_lessons int not null default 24 check (total_lessons >= 1),
  created_at   timestamptz not null default now(),
  unique (center_id, name)
);

create index if not exists courses_center_idx on public.courses (center_id);

alter table public.groups
  add column if not exists course_id uuid references public.courses (id) on delete set null;

-- Seed one default course per centre and point existing groups at it.
insert into public.courses (center_id, name, description, total_lessons)
select c.id, 'IELTS General Preparation', 'Программа подготовки к IELTS по умолчанию', 24
  from public.language_centers c
 where not exists (
   select 1 from public.courses x
    where x.center_id = c.id and x.name = 'IELTS General Preparation'
 );

update public.groups g
   set course_id = (select id from public.courses c where c.center_id = g.center_id limit 1)
 where g.course_id is null and g.center_id is not null;

-- ---------------------------------------------------------------------------
-- 3. Enrollment — student ↔ group as a real, dated relation.
-- ---------------------------------------------------------------------------
create table if not exists public.enrollments (
  id          uuid primary key default gen_random_uuid(),
  group_id    uuid not null references public.groups (id) on delete cascade,
  student_id  uuid not null references public.students (id) on delete cascade,
  status      text not null default 'active' check (status in ('active', 'completed', 'withdrawn')),
  enrolled_on date not null default current_date,
  created_at  timestamptz not null default now(),
  unique (group_id, student_id)
);

create index if not exists enrollments_group_idx   on public.enrollments (group_id);
create index if not exists enrollments_student_idx on public.enrollments (student_id);

-- A direct pointer for the common "which group is this student in" read. The
-- text column student_group remains the legacy mirror.
alter table public.students
  add column if not exists group_id uuid references public.groups (id) on delete set null;

create index if not exists students_group_idx on public.students (group_id);

-- Backfill from the existing strings, creating any group that only ever
-- existed as text on a student row.
insert into public.groups (name, center_id)
select distinct s.student_group,
       (select id from public.language_centers order by created_at limit 1)
  from public.students s
 where s.student_group is not null
   and s.student_group <> ''
   and not exists (select 1 from public.groups g where g.name = s.student_group)
on conflict (name) do nothing;

update public.students s
   set group_id = g.id
  from public.groups g
 where g.name = s.student_group
   and s.group_id is distinct from g.id;

insert into public.enrollments (group_id, student_id)
select s.group_id, s.id
  from public.students s
 where s.group_id is not null
on conflict (group_id, student_id) do nothing;

-- ---------------------------------------------------------------------------
-- 4. Keep the FK and the legacy text column in step, in BOTH directions.
--
--    This has to be a trigger rather than a one-off backfill: setup.sql applies
--    the migrations and then re-runs the seeds, which delete-and-reinsert the
--    student rows with only student_group set. A one-shot UPDATE is wiped by
--    that; a trigger makes the link self-healing for any future insert too.
-- ---------------------------------------------------------------------------
create or replace function public.sync_student_group()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.group_id is not null then
    -- FK wins: mirror its name into the legacy text column.
    select name into new.student_group from public.groups where id = new.group_id;
  elsif new.student_group is not null and new.student_group <> '' then
    -- Only the legacy string was supplied (seeds, older code): resolve the FK.
    select id into new.group_id from public.groups where name = new.student_group;
  end if;
  return new;
end;
$$;

drop trigger if exists students_sync_group_name on public.students;
drop trigger if exists students_sync_group on public.students;
create trigger students_sync_group
  before insert or update of group_id, student_group on public.students
  for each row execute function public.sync_student_group();

-- Enrollment follows the student's group automatically, for the same reason.
create or replace function public.sync_student_enrollment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.group_id is not null then
    insert into public.enrollments (group_id, student_id)
    values (new.group_id, new.id)
    on conflict (group_id, student_id) do nothing;
  end if;
  return new;
end;
$$;

drop trigger if exists students_sync_enrollment on public.students;
create trigger students_sync_enrollment
  after insert or update of group_id on public.students
  for each row execute function public.sync_student_enrollment();

-- Re-run the backfill for rows that already exist (the triggers only fire on
-- write). Harmless when everything is already linked.
update public.students s
   set group_id = g.id
  from public.groups g
 where g.name = s.student_group
   and s.group_id is distinct from g.id;

-- ---------------------------------------------------------------------------
-- 5. RLS. `groups` had it enabled with NO policy, which is why a teacher's
--    session could not read it at all (worked around in Stage 1).
-- ---------------------------------------------------------------------------
alter table public.courses     enable row level security;
alter table public.enrollments enable row level security;

-- Groups: staff read their centre; a student reads their own group; a parent
-- reads their wards' groups.
drop policy if exists "groups_select_center" on public.groups;
create policy "groups_select_center" on public.groups
  for select using (center_id in (select public.current_user_center_ids()));

drop policy if exists "groups_write_center" on public.groups;
create policy "groups_write_center" on public.groups
  for all
  using (center_id in (select public.current_user_center_ids()))
  with check (center_id in (select public.current_user_center_ids()));

drop policy if exists "groups_select_member" on public.groups;
create policy "groups_select_member" on public.groups
  for select using (
    id in (
      select group_id from public.students
       where id = public.current_user_student_id()
          or id in (select public.current_user_ward_ids())
    )
  );

-- Courses: readable by anyone in the centre; writable by staff of that centre.
drop policy if exists "courses_rw_center" on public.courses;
create policy "courses_rw_center" on public.courses
  for all
  using (center_id in (select public.current_user_center_ids()))
  with check (center_id in (select public.current_user_center_ids()));

drop policy if exists "courses_select_member" on public.courses;
create policy "courses_select_member" on public.courses
  for select using (
    id in (
      select g.course_id from public.groups g
       join public.students s on s.group_id = g.id
      where s.id = public.current_user_student_id()
         or s.id in (select public.current_user_ward_ids())
    )
  );

-- Enrollments: staff manage those in their centre; a student/parent may read
-- their own rows.
drop policy if exists "enrollments_rw_center" on public.enrollments;
create policy "enrollments_rw_center" on public.enrollments
  for all
  using (
    student_id in (
      select id from public.students
       where center_id in (select public.current_user_center_ids())
    )
  )
  with check (
    student_id in (
      select id from public.students
       where center_id in (select public.current_user_center_ids())
    )
  );

drop policy if exists "enrollments_select_self" on public.enrollments;
create policy "enrollments_select_self" on public.enrollments
  for select using (
    student_id = public.current_user_student_id()
    or student_id in (select public.current_user_ward_ids())
  );

-- Guardianships: 0011 gave this table SELECT policies only, so nobody but the
-- service role could revoke a link. Staff of the child's centre may now manage
-- them (creating one still needs auth.users, hence the admin path in the API).
drop policy if exists "guardianships_staff_write" on public.guardianships;
create policy "guardianships_staff_write" on public.guardianships
  for all
  using (
    student_id in (
      select id from public.students
       where center_id in (select public.current_user_center_ids())
    )
  )
  with check (
    student_id in (
      select id from public.students
       where center_id in (select public.current_user_center_ids())
    )
  );

-- ===== migrations/0013_homework_lifecycle.sql =====

-- EduFlow — Stage 3a: the homework lifecycle (assign → submit → grade).
--
-- The tables have existed since 0004 but were never reachable: `homework` had
-- RLS enabled with NO policy (invisible to every session, exactly like `groups`
-- before 0012), and homework_submissions was scoped to staff only, so a student
-- could not see — let alone hand in — their own work. The interactive screens
-- have been running on in-memory React state that is lost on reload.

-- ---------------------------------------------------------------------------
-- 1. Columns the workflow needs.
-- ---------------------------------------------------------------------------
alter table public.homework
  add column if not exists group_id  uuid references public.groups (id) on delete cascade,
  add column if not exists min_words int,
  add column if not exists created_by uuid references auth.users (id) on delete set null;

create index if not exists homework_group_id_idx on public.homework (group_id);

alter table public.homework_submissions
  -- Per-criterion IELTS writing marks, shown on the review screen.
  add column if not exists criteria  jsonb,
  add column if not exists graded_by uuid references auth.users (id) on delete set null,
  add column if not exists graded_at timestamptz;

-- ---------------------------------------------------------------------------
-- 2. Keep homework.group_id and the legacy group_name in step, both ways —
--    same reasoning as students in 0012: seeds and older code write only the
--    text column, and the UI still reads it.
-- ---------------------------------------------------------------------------
create or replace function public.sync_homework_group()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.group_id is not null then
    select name into new.group_name from public.groups where id = new.group_id;
  elsif new.group_name is not null and new.group_name <> '' then
    select id into new.group_id from public.groups where name = new.group_name;
  end if;
  return new;
end;
$$;

drop trigger if exists homework_sync_group on public.homework;
create trigger homework_sync_group
  before insert or update of group_id, group_name on public.homework
  for each row execute function public.sync_homework_group();

update public.homework h
   set group_id = g.id
  from public.groups g
 where g.name = h.group_name
   and h.group_id is distinct from g.id;

-- ---------------------------------------------------------------------------
-- 3. A student may hand work in, but must never mark their own paper.
--    RLS decides WHICH rows are writable; this trigger decides WHICH COLUMNS,
--    which RLS cannot express. Defence in depth: the API already restricts the
--    fields it writes, but the browser holds the anon key and could call
--    PostgREST directly.
-- ---------------------------------------------------------------------------
create or replace function public.guard_submission_grading()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.current_user_role() = 'student' then
    if new.band_score is distinct from old.band_score
       or new.feedback is distinct from old.feedback
       or new.criteria is distinct from old.criteria
       or new.graded_by is distinct from old.graded_by then
      raise exception 'Студент не может выставлять оценку или отзыв';
    end if;
    -- A student may only move their work forward to "submitted".
    if new.status not in ('assigned', 'submitted') then
      raise exception 'Недопустимый статус для студента: %', new.status;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists submissions_guard_grading on public.homework_submissions;
create trigger submissions_guard_grading
  before update on public.homework_submissions
  for each row execute function public.guard_submission_grading();

-- ---------------------------------------------------------------------------
-- 4. RLS.
-- ---------------------------------------------------------------------------

-- homework: staff manage their centre's; students and parents read what is
-- assigned to the group they belong to.
drop policy if exists "homework_rw_center" on public.homework;
create policy "homework_rw_center" on public.homework
  for all
  using (
    group_id in (
      select id from public.groups
       where center_id in (select public.current_user_center_ids())
    )
  )
  with check (
    group_id in (
      select id from public.groups
       where center_id in (select public.current_user_center_ids())
    )
  );

drop policy if exists "homework_select_member" on public.homework;
create policy "homework_select_member" on public.homework
  for select using (
    group_id in (
      select group_id from public.students
       where id = public.current_user_student_id()
          or id in (select public.current_user_ward_ids())
    )
  );

-- homework_submissions: the centre policy from 0004 stays for staff. Add the
-- student's own row (read + hand in) and the parent's read-only view.
drop policy if exists "hw_submissions_select_self" on public.homework_submissions;
create policy "hw_submissions_select_self" on public.homework_submissions
  for select using (
    student_id = public.current_user_student_id()
    or student_id in (select public.current_user_ward_ids())
  );

drop policy if exists "hw_submissions_update_self" on public.homework_submissions;
create policy "hw_submissions_update_self" on public.homework_submissions
  for update
  using (student_id = public.current_user_student_id())
  with check (student_id = public.current_user_student_id());

-- Insert is staff-only (assigning work). A student never creates a row; the
-- assignment already exists for them to fill in.

-- ===== migrations/0014_attendance_sessions.sql =====

-- EduFlow — Stage 3b: class sessions and persistent attendance.
--
-- `attendance` has existed since 0004 but only staff could see it (no student/
-- parent read policy), it hung from a bare date + group_name string rather
-- than a class occurrence, and the UI never wrote it anywhere. Also, the
-- roster's headline `students.attendance` percentage was a seeded number with
-- no relation to the marks; it now recomputes from the real rows.

-- ---------------------------------------------------------------------------
-- 1. class_sessions — one row per group per teaching day. Created lazily when
--    attendance is first marked for that day, so no scheduling UI is required
--    yet; a future timetable feature can pre-create rows with topics.
-- ---------------------------------------------------------------------------
create table if not exists public.class_sessions (
  id         uuid primary key default gen_random_uuid(),
  group_id   uuid not null references public.groups (id) on delete cascade,
  date       date not null,
  topic      text,
  lesson_number int,
  created_at timestamptz not null default now(),
  unique (group_id, date)
);

create index if not exists class_sessions_group_idx on public.class_sessions (group_id, date);

-- ---------------------------------------------------------------------------
-- 2. attendance gains real links: the group (FK) and the session.
-- ---------------------------------------------------------------------------
alter table public.attendance
  add column if not exists group_id   uuid references public.groups (id) on delete set null,
  add column if not exists session_id uuid references public.class_sessions (id) on delete set null,
  add column if not exists marked_by  uuid references auth.users (id) on delete set null;

create index if not exists attendance_group_idx   on public.attendance (group_id, date);
create index if not exists attendance_session_idx on public.attendance (session_id);

-- Resolve group_id from the legacy string (and vice versa), then attach the
-- session row, creating it for that group+date if it does not exist yet.
create or replace function public.sync_attendance_links()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.group_id is null and new.group_name is not null and new.group_name <> '' then
    select id into new.group_id from public.groups where name = new.group_name;
  elsif new.group_id is not null and (new.group_name is null or new.group_name = '') then
    select name into new.group_name from public.groups where id = new.group_id;
  end if;

  if new.group_id is not null and new.session_id is null then
    insert into public.class_sessions (group_id, date)
    values (new.group_id, new.date)
    on conflict (group_id, date) do nothing;
    select id into new.session_id
      from public.class_sessions
     where group_id = new.group_id and date = new.date;
  end if;
  return new;
end;
$$;

drop trigger if exists attendance_sync_links on public.attendance;
create trigger attendance_sync_links
  before insert or update of group_id, group_name, date on public.attendance
  for each row execute function public.sync_attendance_links();

-- Backfill existing rows (the trigger only fires on writes).
update public.attendance a
   set group_id = g.id
  from public.groups g
 where g.name = a.group_name
   and a.group_id is distinct from g.id;

-- ---------------------------------------------------------------------------
-- 3. The roster's headline percentage becomes an honest number: recompute
--    students.attendance from the marks whenever one changes. Present and late
--    both count as attended (late is not absence), matching the tracker's
--    "на занятии" counter.
-- ---------------------------------------------------------------------------
create or replace function public.recompute_student_attendance()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  sid uuid := coalesce(new.student_id, old.student_id);
  pct int;
begin
  select coalesce(round(100.0 * count(*) filter (where status in ('present','late'))
                  / nullif(count(*), 0)), 0)::int
    into pct
    from public.attendance
   where student_id = sid;

  -- No marks at all → leave the seeded percentage alone rather than zeroing
  -- every dashboard the moment the feature ships.
  if pct is not null and exists (select 1 from public.attendance where student_id = sid) then
    update public.students set attendance = pct where id = sid;
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists attendance_recompute_pct on public.attendance;
create trigger attendance_recompute_pct
  after insert or update of status or delete on public.attendance
  for each row execute function public.recompute_student_attendance();

-- ---------------------------------------------------------------------------
-- 4. RLS. Staff keep the centre policy from 0004; a student and their parent
--    may now READ the student's own marks. Writing stays staff-only.
-- ---------------------------------------------------------------------------
drop policy if exists "attendance_select_self" on public.attendance;
create policy "attendance_select_self" on public.attendance
  for select using (
    student_id = public.current_user_student_id()
    or student_id in (select public.current_user_ward_ids())
  );

alter table public.class_sessions enable row level security;

drop policy if exists "class_sessions_rw_center" on public.class_sessions;
create policy "class_sessions_rw_center" on public.class_sessions
  for all
  using (
    group_id in (
      select id from public.groups
       where center_id in (select public.current_user_center_ids())
    )
  )
  with check (
    group_id in (
      select id from public.groups
       where center_id in (select public.current_user_center_ids())
    )
  );

drop policy if exists "class_sessions_select_member" on public.class_sessions;
create policy "class_sessions_select_member" on public.class_sessions
  for select using (
    group_id in (
      select group_id from public.students
       where id = public.current_user_student_id()
          or id in (select public.current_user_ward_ids())
    )
  );

-- ===== migrations/0015_group_capacity_teacher_contact.sql =====

-- EduFlow — Stage 5: give the director dashboard real columns to report.
--
-- Two figures on that screen were manufactured rather than stored:
--   * group capacity was Math.max(headcount, ceil(headcount/4)*4) — a formula
--     derived from the headcount itself, so every group always looked nearly
--     full and "6/8" could never mean anything;
--   * the staff roster's email came from a hardcoded list in lib/admin-data,
--     because public.teachers had nowhere to keep one.

alter table public.groups
  add column if not exists capacity int check (capacity is null or capacity between 1 and 100);

alter table public.teachers
  add column if not exists email text;

comment on column public.groups.capacity is
  'Nominal seats for the group. NULL means "not set" — the dashboard shows the headcount alone rather than inventing a denominator.';

-- Seed a plausible starting capacity for existing groups: the current
-- headcount rounded up to the next multiple of four, floored at four. This is
-- the same shape the old formula produced, but it is now a stored value a
-- director can correct — not a number recomputed from the roster every render.
update public.groups g
   set capacity = greatest(4, ceil(coalesce(c.n, 0) / 4.0) * 4)
  from (
    select group_id, count(*)::int as n
      from public.enrollments
     where status = 'active'
     group by group_id
  ) c
 where c.group_id = g.id
   and g.capacity is null;

-- Groups with nobody enrolled still need a sane default.
update public.groups set capacity = 8 where capacity is null;

